const usageByProvider = `-- name: UsageByProvider :many
SELECT
    NULL::date AS day,
    ''::text AS model,
    ''::text AS account_id,
    ''::text AS account_name,
    a.provider_id AS provider_id,
    COALESCE(sum(d.requests), 0)::bigint AS requests,
    COALESCE(sum(d.input_tokens), 0)::bigint AS input_tokens,
    COALESCE(sum(d.output_tokens), 0)::bigint AS output_tokens,
    COALESCE(sum(d.cache_read_tokens), 0)::bigint AS cache_read_tokens,
    COALESCE(sum(d.cache_write_tokens), 0)::bigint AS cache_write_tokens,
    COALESCE(sum(d.reasoning_tokens), 0)::bigint AS reasoning_tokens,
    bool_and(d.cost_reported) AS cost_reported,
    COALESCE((
        SELECT jsonb_agg(jsonb_build_object('micro', c.micro, 'currency', c.currency) ORDER BY c.currency)
        FROM (
            SELECT sum(d2.cost_micro)::bigint AS micro, d2.cost_currency::text AS currency
            FROM usage_daily d2
            JOIN accounts a2 ON a2.org_id = d2.org_id AND a2.id = d2.account_id
            WHERE d2.org_id = $1::uuid
              AND account_visible($1::uuid, $2::uuid, $3::boolean, d2.account_id)
              AND a2.provider_id = a.provider_id
              AND ($4::uuid IS NULL OR d2.account_id = $4::uuid)
              AND ($5::text IS NULL OR a2.provider_id = $5::text)
            GROUP BY d2.cost_currency
        ) c
    ), '[]'::jsonb)::text AS cost
FROM usage_daily d
JOIN accounts a ON a.org_id = d.org_id AND a.id = d.account_id
WHERE d.org_id = $1::uuid
  AND account_visible($1::uuid, $2::uuid, $3::boolean, d.account_id)
  AND d.day >= $6
  AND d.day <= $7
  AND ($4::uuid IS NULL OR d.account_id = $4::uuid)
  AND ($5::text IS NULL OR a.provider_id = $5::text)
GROUP BY a.provider_id
ORDER BY a.provider_id
`

type UsageByProviderParams struct {
	OrgID      string
	UserID     string
	IsAdmin    bool
	AccountID  *string
	ProviderID *string
	FromDay    time.Time
	ToDay      time.Time
}

type UsageByProviderRow struct {
	Day              *time.Time
	Model            string
	AccountID        string
	AccountName      string
	ProviderID       string
	Requests         int64
	InputTokens      int64
	OutputTokens     int64
	CacheReadTokens  int64
	CacheWriteTokens int64
	ReasoningTokens  int64
	CostReported     bool
	Cost             string
}

func (q *Queries) UsageByProvider(ctx context.Context, arg UsageByProviderParams) ([]UsageByProviderRow, error) {
	rows, err := q.db.Query(ctx, usageByProvider,
		arg.OrgID,
		arg.UserID,
		arg.IsAdmin,
		arg.AccountID,
		arg.ProviderID,
		arg.FromDay,
		arg.ToDay,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []UsageByProviderRow{}
	for rows.Next() {
		var i UsageByProviderRow
		if err := rows.Scan(
			&i.Day,
			&i.Model,
			&i.AccountID,
			&i.AccountName,
			&i.ProviderID,
			&i.Requests,
			&i.InputTokens,
			&i.OutputTokens,
			&i.CacheReadTokens,
			&i.CacheWriteTokens,
			&i.ReasoningTokens,
			&i.CostReported,
			&i.Cost,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}
